function newEmergencyOracle(string calldata description) external onlyJojoTeam {
    address newOracle = address(
        new EmergencyOracle(jojoTeam, description)
    );
    emit NewEmergencyOracle(msg.sender, newOracle);
}

modifier onlyJojoTeam() {
    require(msg.sender != jojoTeam, "Caller is not the JOJO team");
    _;
}
